class Meta(type):
    def __getattribute__(self, name):
        if name == '__name__': raise AssertionError('guest name lookup')
        return type.__getattribute__(self, name)
class L(list, metaclass=Meta): pass
receiver = L([1])
method = getattr(receiver, 'append')
L.__name__ = 'Renamed'
try:
    method(unexpected=1)
except BaseException as error:
    actual = (type(error).__name__, str(error), error.args)

print(repr(actual))

