class Meta(type):
    def __getattribute__(self, name):
        if name == '__qualname__':
            events.append(name)
            if 'text' == 'raise': raise ValueError('metadata')
            if 'text' == 'invalid': return 7
            if 'text' == 'subtype': return Text('Stored')
            return 'Visible'
        return type.__getattribute__(self, name)
